import numpy as np
def feats(w):
    c=np.cos(w*t); s=np.sin(w*t)
    base=[np.ones_like(t),x,v,x**3,x**2,np.abs(v)*v,x*np.abs(x),v**3,x*v,np.sign(v),np.sin(v),np.cos(x)]
    return np.column_stack(base+[c,s,c*x,s*x,c*v,s*v])
best=None
for w in np.linspace(0.05,3,600):
    X=feats(w)
    c,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
